-- GENERATED by `wfj generate` from data/gossip/gossip-82.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["820416bc52658acb"] = { "Dovrò uccidere qualcosa, vero?", "." },
  ["8204cbeafc364eac"] = { "Conosco queste foreste come se fossero parte di me... ma sappi che c'è ancora molto da imparare da loro, e molti pericoli ancora nascosti.", "." },
  ["821d4c7de8bddf8a"] = { "Salve, Sovik, voglio vedere la tua merce.", "." },
  ["821fc9d6d8ed9b12"] = { "Parlami della fede, padre.", "." },
  ["821ffd56adfef25d"] = { "Voglio combattere!", "." },
  ["8223514b518d388b"] = { "Ho fatto ritorno alla mia vecchia casa perché il mio sapere possa essere tramandato. A differenza dei non morti senza cervello che mi circondano, ho scelto questa non vita per ragioni mie.\n\nI silitidi sono avversari temibili, {name}. Ho imparato a rispettarli quanto li disprezzo.\n\nGran parte della loro letalità deriva dalla robustezza e dalla leggerezza della loro chitina, che ho imparato a lavorare per farne armature. Visto che a quanto pare abbiamo un nemico comune, ti insegnerò il mio mestiere.", "." },
  ["82235f8926dca6cf"] = { "Mi serve aiuto per recuperare un pezzo delle mie Demoniac's Threads, Al'tabim.", "." },
  ["8235c414e2e0084b"] = { "Hai davvero bisogno di chiederlo? Non lo senti? Il potentissimo re Rastakhan ha mandato qui il suo Servitore e la sua Mano in missione diplomatica?", "." },
  ["8243b82f958494cb"] = { "Cerca Shim'la all'ingresso sud della Hunter's Hall, nella ⟦Valley of Honor=Valle dell'Onore⟧.", "." },
  ["8245b939720d4e5e"] = { "Cosa NON c'è da fare, vorrai dire!\n\nTutti i locandieri del mondo distribuiscono dolcetti di «dolcetto o scherzetto», e molte città sono decorate per la festa! E poi, la sera, appena fuori ⟦Undercity=Sepulcra⟧, c'è la festa dell'Uomo di Paglia.\n\nUn'ultima cosa: ho sentito che una bambina malata dell'orfanotrofio qui a Orgrimmar cerca qualcuno che la aiuti a raccogliere dolcetti per la festa... forse potresti aiutarla tu?", "." },
  ["824d498bb5531cec"] = { "E se non lo farai, allora per me non c'è davvero speranza.", "." },
  ["825c03bd486d40be"] = { "Ho il totem della purificazione, {name}.", "." },
  ["825d0b4b887a29c4"] = { "Dove sono tutti?", "." },
  ["825f95924040288b"] = { "Carne di {race}... devo nutrirmi!", "." },
  ["8260098fe9800923"] = { "Metti i bracciali sopra il braciere e versi nella fiamma le ultime gocce della pozione di Brine. Le gocce crepitano a contatto con la fiamma e cominci a recitare le semplici parole che ti ha insegnato Islen...", "." },
  ["82642bb5bd8bbc64"] = { "Sì, amico, tu vuoi Jandi's Arboretum. L'ho detto davvero? Glok'tar, la stanchezza mi gioca brutti scherzi! Segui i gradini di legno dietro Asoran's Market, nella Valle della Saggezza, fino al Varcolargo, e troverai Jandi's al piano superiore.", "." },
  ["827033a445b67c60"] = { "Parlami della promozione iCoke.", "." },
  ["8270374f7c9ea48c"] = { "Il Flagello prevarrà!", "." },
  ["82797109b01101b0"] = { "Usa bastone, di' a Raze cosa fare! Mostra a Raze bracconiere! Raze spacca!", "." },
  ["827afb74d8322cbc"] = { "Questa terra è contaminata. Bisogna invocare Ivus!", "." },
  ["8284abcc195a1492"] = { "%s soffia via il fumo dalla canna del fucile..", "." },
  ["828dcc9011537129"] = { "Chiave... prendi la chiave... Gerstahn ha... chiave.", "." },
  ["82902b43aeb26e51"] = { "È ora che tu passi a un maestro più esperto. Nella Roccaforte di Piumaluna di Feralas vive l'elfa della notte ⟦Kylanna Windwhisper=Kylanna Parlavento⟧. Ha una mente brillante; senza dubbio potrà addestrarti ancora.", "." },
  ["82953d7fd5be8bb3"] = { "Tre teste ho, una quarta mi serve. Sarà quella di Mug'Thol, o sarà la tua, {name}. Questo te lo prometto.", "." },
  ["8296313023fb44c2"] = { "Lo scrigno risucchia %s!", "." },
  ["82997d78eae23952"] = { "Questa pelle non è ancora pronta per essere lavorata. Vorrei che non ci volesse così tanto a fare il cuoio. Dev'esserci un modo per ridurre tutta questa attesa. Non può far bene alla salute, sai?", "." },
  ["829cdb307f8e9e7a"] = { "Bevi pure! Ce n'è dell'altro!", "." },
  ["82a4f7d115bdd829"] = { "Ehm, salve! Se sei qui per riscuotere tasse e/o per una citazione, allora mi hai di sicuro scambiato per qualcun altro. Mi dispiace tanto!", "." },
  ["82a9e9692b1c8b02"] = { "Ma salve di nuovo, {name}! Non so per quanto ancora continuerò a provare ad aprire un negozio in mezzo al nulla. Comunque, visto che in passato mi hai dato una mano, ti mostrerò qualche articolo che potrebbe interessarti!", "." },
  ["82aadc52e64e93ff"] = { "Il Flagello non prevarrà!", "." },
  ["82b4e7cd60337d61"] = { "Cavalchiamo al tuo comando!", "." },
  ["82bd005e48caf422"] = { "Occupati di questo, {name}! Devo prepararmi a risvegliare Naralex!", "." },
  ["82beecccc4ec9ce9"] = { "Se vuoi guarire dall'\"ite\" dovrai impegnarti più di così, {name}. Dove sono i reagenti per la cura?", "." },
  ["82c34c447a4d9aa1"] = { "Mio figlio, Taelan, era solo un bambino quando fui riconosciuto colpevole di tradimento ed esiliato dall'⟦Alliance=Alleanza⟧. Scelsi di restare qui per poter vegliare su di lui, per assicurarmi in qualche modo che crescesse come un uomo d'onore.\n\nCome speravo, prese il mio posto come signore di Mardenholde; ma, per un crudele scherzo del destino, si unì alla ⟦Scarlet Crusade=Crociata Scarlatta⟧. Ora ne è il gran signore, {race}.", "." },
  ["82cbf923dfb3ddd8"] = { "In effetti.", "." },
  ["82d40f960f176e4a"] = { "Pesca", "." },
  ["82d45eb6ec2d68f7"] = { "Porto notizie sul nostro conflitto con i Non Morti rinnegati.", "." },
  ["82d772ee6c83b2ec"] = { "Lee Brown passa tutto il giorno a pescare vicino al ⟦Crystal Lake=Lago di Cristallo⟧. Probabilmente ha qualche storia da raccontare e qualche consiglio da darti.", "." },
  ["82db41e3b281b6bd"] = { "Ben <trovato/trovata>, {name}. Dobbiamo essere brevi, perché c'è molto da fare.", "." },
  ["82e6b5bc28d40c93"] = { "%s saluta {name} con la mano.", "." },
  ["82ebd807f4f9cbe4"] = { "Vuoi diventare tassidermista? Non mi piace chi pensa di potermi impagliare e appendere al muro solo perché mi crede un cadavere. No? Bene! Cerca Rand Rhobart in un accampamento a sud-est del paese. Per arrivarci, prendi la strada che esce a sud-est da Brill e gira a sinistra all'incrocio.", "." },
  ["82ee6942c8cb1f66"] = { "Sarebbe un onore per me addestrarti nell'uso delle armi che padroneggio, se hai dentro di te la capacità di imparare.", "." },
  ["82eff513862baeee"] = { "Siamo gli ultimi della razza dei mezzorsi... La tribù dei Mordilegno resta incorrotta, eppure affrontiamo la stessa ostilità da parte degli estranei; i più credono che non sia possibile... che possano davvero esistere mezzorsi sfuggiti alla corruzione...\n\nIrritati da chi si fa nemici troppo in fretta, i miei fratelli ora attaccano chiunque si avvicini; non si fidano di nessuno.\n\nMa forse, se ti sforzi di presentarti a loro in pace, potrebbero considerarti dalla loro parte.", "." },
})
